package com.inventra.backend.model; public class PurchaseOrderItem { private String productId; private int quantity; private double unitCost; private int receivedQuantity; public PurchaseOrderItem(){} public PurchaseOrderItem(String p,int q,double c){productId=p;quantity=q;unitCost=c;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public double getUnitCost(){return unitCost;} public void setUnitCost(double v){unitCost=v;} public int getReceivedQuantity(){return receivedQuantity;} public void setReceivedQuantity(int v){receivedQuantity=v;} }
